<?= $this->extend('admin/admin_layout') ?>
<?= $this->section('content') ?>
<?php $submissionFor = static function (array $items, int $adoptionId, string $checkpoint): ?array { foreach ($items as $item) if ((int) $item['adoption_id'] === $adoptionId && $item['checkpoint'] === $checkpoint) return $item; return null; }; ?>
<div class="mb-6"><h1 class="text-3xl font-bold tracking-[-.025em]">Post-Adoption Monitoring</h1><p class="text-slate-500">Track 3-day, 3-week, and 3-month adopter updates.</p></div>
<div class="mb-6 grid gap-6 md:grid-cols-4"><?php foreach ([['Under Monitoring', count($cases)], ['Awaiting Review', count(array_filter($submissions, fn($s) => $s['status'] === 'Pending'))], ['Verified', count(array_filter($submissions, fn($s) => $s['status'] === 'Verified'))], ['Flagged', count(array_filter($submissions, fn($s) => $s['status'] === 'Flagged'))]] as $stat): ?><div class="card"><div class="text-2xl font-bold"><?= esc($stat[1]) ?></div><div class="text-sm font-medium text-slate-500"><?= esc($stat[0]) ?></div></div><?php endforeach; ?></div>
<div class="card overflow-x-auto p-0"><table class="w-full text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3 text-left">Adopter</th><th class="px-4 py-3 text-left">Cat</th><th class="px-4 py-3 text-left">Adoption Date</th><th class="px-4 py-3 text-left">3-day</th><th class="px-4 py-3 text-left">3-week</th><th class="px-4 py-3 text-left">3-month</th></tr></thead><tbody><?php foreach ($cases as $case): ?><?php $dates = monitoringCheckpoints($case['adoption_date']); ?><tr class="border-t"><td class="px-4 py-3 font-semibold"><?= esc($case['adopter_name']) ?></td><td class="px-4 py-3"><?= esc($case['animal_name']) ?></td><td class="px-4 py-3"><?= esc($case['adoption_date']) ?></td><?php foreach (['3-day','3-week','3-month'] as $checkpoint): ?><?php $submission = $submissionFor($submissions, (int) $case['id'], $checkpoint); ?><td class="px-4 py-3"><?php if ($submission): ?><span class="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold <?= $submission['status'] === 'Verified' ? 'bg-adopted-50 text-adopted-700' : ($submission['status'] === 'Flagged' ? 'bg-red-50 text-red-700' : 'bg-amber-50 text-amber-700') ?>"><i data-lucide="<?= $submission['status'] === 'Verified' ? 'check' : ($submission['status'] === 'Flagged' ? 'flag' : 'clock') ?>" class="h-3.5 w-3.5"></i><?= esc($submission['status']) ?></span><?php else: ?><span class="inline-flex items-center gap-1 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-500"><i data-lucide="circle" class="h-3.5 w-3.5"></i>Not submitted</span><p class="mt-1 text-xs text-slate-400">Due <?= esc(date('M d', strtotime($dates[$checkpoint]))) ?></p><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
<div class="mt-8"><div class="mb-4"><h2 class="text-xl font-bold text-slate-900">Submitted Updates</h2><p class="mt-1 text-sm text-slate-500">Each card is one adopter and cat. Their 3-day, 3-week, and 3-month check-ins stay together.</p></div><?php if (empty($submittedCases)): ?><div class="card text-sm text-slate-500">No adopter updates have been submitted yet.</div><?php else: ?><div class="space-y-6"><?php foreach ($submittedCases as $submittedCase): ?><?php $checkpointDates = ! empty($submittedCase['adoption_date']) ? monitoringCheckpoints($submittedCase['adoption_date']) : []; ?><article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><header class="flex flex-col gap-3 border-b border-slate-100 bg-gradient-to-r from-rescue-50 to-white px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div class="flex items-center gap-3"><div class="flex h-11 w-11 items-center justify-center rounded-xl bg-rescue-600 text-white"><i data-lucide="heart-handshake" class="h-5 w-5"></i></div><div><h3 class="font-bold text-slate-900"><?= esc($submittedCase['adopter_name']) ?> <span class="font-normal text-slate-400">·</span> <?= esc($submittedCase['animal_name']) ?></h3><p class="text-sm text-slate-500">One monitoring case · Adopted <?= ! empty($submittedCase['adoption_date']) ? esc(date('M d, Y', strtotime($submittedCase['adoption_date']))) : 'date unavailable' ?></p></div></div><span class="rounded-full bg-rescue-100 px-3 py-1 text-xs font-bold text-rescue-700"><?= count($submittedCase['checkpoints']) ?>/3 check-ins received</span></header><div class="grid divide-y divide-slate-100 lg:grid-cols-3 lg:divide-x lg:divide-y-0"><?php foreach (['3-day' => '3-Day Check-in', '3-week' => '3-Week Check-in', '3-month' => '3-Month Check-in'] as $checkpoint => $label): ?><?php $submission = $submittedCase['checkpoints'][$checkpoint] ?? null; ?><section class="p-5"><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-bold uppercase tracking-wider text-rescue-600"><?= esc($label) ?></p><?php if (! empty($checkpointDates[$checkpoint])): ?><p class="mt-1 text-xs text-slate-400">Due <?= esc(date('M d, Y', strtotime($checkpointDates[$checkpoint]))) ?></p><?php endif; ?></div><?php if ($submission): ?><?= statusBadge($submission['status']) ?><?php else: ?><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-500">Not submitted</span><?php endif; ?></div><?php if (! $submission): ?><div class="mt-8 flex min-h-24 items-center justify-center rounded-xl border border-dashed border-slate-200 bg-slate-50 px-4 text-center text-sm text-slate-400">This check-in has not been submitted.</div><?php else: ?><p class="mt-4 text-xs font-medium text-slate-500">Submitted <?= esc(date('M d, Y g:i A', strtotime($submission['submission_date']))) ?></p><div class="mt-3 flex gap-3"><?php if (! empty($submission['photo_url'])): ?><a target="_blank" href="<?= esc(base_url($submission['photo_url'])) ?>" class="shrink-0"><img src="<?= esc(base_url($submission['photo_url'])) ?>" class="h-20 w-20 rounded-xl object-cover" alt="<?= esc($label) ?> photo"></a><?php endif; ?><div class="min-w-0"><p class="text-sm font-semibold text-slate-700"><?= esc(ucfirst($submission['health_status'] ?: 'General')) ?> update</p><p class="mt-1 line-clamp-4 text-sm leading-5 text-slate-600"><?= esc($submission['behavior_notes']) ?></p></div></div><?php if ($submission['status'] === 'Pending'): ?><form method="post" action="<?= site_url('admin/monitoring/' . $submission['id'] . '/review') ?>" class="mt-4 flex flex-wrap gap-2"><?= csrf_field() ?><button name="status" value="Verified" class="btn bg-adopted-600 text-white hover:bg-adopted-700">Approve</button><button name="status" value="Flagged" class="btn border border-red-100 bg-red-50 text-red-600">Flag</button></form><?php endif; ?><?php endif; ?></section><?php endforeach; ?></div></article><?php endforeach; ?></div><?php endif; ?></div>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?>
<script>
document.querySelectorAll('a[target="_blank"][href*="/uploads/updates/"]').forEach(function (link) { link.removeAttribute('target'); });
document.addEventListener('click', function (event) {
    var link = event.target.closest('a[target="_blank"][href*="/uploads/updates/"]');
    if (! link) return;
    event.preventDefault();
    event.stopPropagation();
            var modal = document.createElement('div');
            modal.className = 'fixed inset-0 z-[200] flex items-center justify-center bg-black/90 p-4';
            modal.innerHTML = '<button type="button" style="position:fixed;top:20px;right:20px;z-index:220;background:#fff;color:#0f172a;border:0;border-radius:10px;padding:12px 18px;font-weight:700;font-size:14px;box-shadow:0 4px 16px rgba(0,0,0,.35)">Close</button><img style="max-height:82vh;max-width:100%;border-radius:8px;object-fit:contain" alt="Monitoring update photo"><button type="button" style="position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:220;background:#fff;color:#0f172a;border:0;border-radius:10px;padding:12px 18px;font-weight:700;font-size:14px;box-shadow:0 4px 16px rgba(0,0,0,.35)">← Back to Monitoring</button>';
            modal.querySelector('img').src = link.href;
            modal.querySelectorAll('button').forEach(function (button) { button.onclick = function () { modal.remove(); }; });
            modal.onclick = function (click) { if (click.target === modal) modal.remove(); };
            document.addEventListener('keydown', function closeOnEscape(keyEvent) { if (keyEvent.key !== 'Escape') return; modal.remove(); document.removeEventListener('keydown', closeOnEscape); });
            document.body.appendChild(modal);
}, true);
</script>
<?= $this->endSection() ?>
